--
-- Table structure for table `control_log`
--

DROP TABLE IF EXISTS `control_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `control_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` varchar(16) NOT NULL COMMENT '关联 device.id',
  `action` varchar(10) NOT NULL COMMENT '动作：开启 / 关闭',
  `result` varchar(10) NOT NULL COMMENT '结果：成功 / 失败',
  `operator` varchar(50) DEFAULT NULL COMMENT '操作人，如"农户·张老三"',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_device_time` (`device_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=657 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='灌溉控制日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `control_log`
