--
-- Table structure for table `register_request`
--

DROP TABLE IF EXISTS `register_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `register_request` (
